// Nine physical-iPhone findings; real WebKit screenshots with isolated synthetic data.
const fs=require('node:fs'),path=require('node:path');
const {chromium,webkit}=require('playwright'),seed=require('./ui-fixture.cjs');
const url=process.env.PREVIEW_URL;if(!url)throw Error('PREVIEW_URL required');
const output=path.join(process.env.AUDIT_OUTPUT||'responsive-audit-output','physical-iphone');fs.mkdirSync(output,{recursive:true});
const matrix={},evidence={},screenshots=[],errors=[],isolationErrors=[],beforeObservations={};
async function run(browser,engine,device,width,height,before=false){
 const prefix=(before?'before.':'')+engine+'.'+device,dir=path.join(output,prefix);fs.mkdirSync(dir,{recursive:true});let context,page;
 const check=(key,ok,data)=>{key=prefix+'.'+key;if(before){beforeObservations[key]={result:ok?'PASS':'FAIL',data};return;}matrix[key]=ok?'PASS':'FAIL';if(data!==undefined)evidence[key]=data;console.log(key+' '+matrix[key]+(ok?'':' '+JSON.stringify(data))); };
 async function fresh(role){await context?.close();context=await browser.newContext({viewport:{width,height},deviceScaleFactor:1,hasTouch:device!=='desktop',locale:'de-CH',timezoneId:'Europe/Zurich'});await context.addInitScript(seed);await context.route('**/*',r=>/supabase/i.test(r.request().url())||new URL(r.request().url()).hostname==='vercel.live'?r.abort():r.continue());page=await context.newPage();page.setDefaultTimeout(10000);page.on('pageerror',e=>{const item={prefix,message:e.message};if(/supabase\.co/.test(e.message)&&/access control checks/.test(e.message))isolationErrors.push(item);else errors.push(item);});await page.goto(before?process.env.BASELINE_PREVIEW_URL:url,{waitUntil:'domcontentloaded'});await page.locator('.role-selection').waitFor();if(role){await page.locator('[data-role="'+role+'"]').click();await page.locator('.app-shell').waitFor();if(role==='service'){await page.waitForFunction(()=>sessionStorage.getItem('ambassador-service-entry-transition')!=='pending');await page.locator('.work-area-entry-transition').waitFor({state:'detached'});}}}
 async function shot(state,metrics){await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));const file=path.join(dir,state+'.png');await page.screenshot({path:file,animations:'disabled'});const viewport=await page.evaluate(()=>({width:innerWidth,height:innerHeight,scrollWidth:document.documentElement.scrollWidth}));check('overflow.'+state,viewport.scrollWidth<=width,viewport);screenshots.push({file,prefix,state,viewport,metrics,dataSource:'synthetic only',realDataMutation:false});}
 async function section(name,fn){try{await fn();}catch(e){check(name,false,{error:String(e)});await shot('FAIL-'+name).catch(()=>{});}}
 async function menu(){await page.getByRole('button',{name:'Menü öffnen'}).click();return page.locator('.structured-app-menu').evaluate(menu=>{const css=e=>getComputedStyle(e),line=e=>({top:css(e).borderTopWidth,bottom:css(e).borderBottomWidth,color:css(e).borderTopColor,box:e.getBoundingClientRect().toJSON()});return{sections:[...menu.querySelectorAll('.structured-menu-scroll > section')].map(e=>({section:line(e),rows:[...e.querySelectorAll('.structured-menu-item')].map(line)})),footer:line(menu.querySelector('footer')),items:[...menu.querySelectorAll('.structured-menu-item')].map(e=>({box:e.getBoundingClientRect().toJSON(),text:e.querySelector('span:not(.structured-menu-icon)').getBoundingClientRect().toJSON()}))};});}
 async function editorMetrics(){return page.locator('.guest-edit-modal').evaluate(e=>{const r=x=>x.getBoundingClientRect().toJSON(),head=e.querySelector('.modal-head'),body=e.querySelector('.modal-body'),footer=e.querySelector('.modal-actions'),field=e.querySelector('textarea'),label=e.querySelector('.guest-edit-grid label > span'),last=e.querySelector('.remark-edit-open'),hit=x=>{const b=r(x);return x.contains(document.elementFromPoint(b.x+b.width/2,b.y+b.height/2));};return{modal:r(e),head:r(head),body:r(body),footer:r(footer),label:r(label),field:r(field),last:r(last),buttons:[...footer.querySelectorAll('button')].map(x=>({box:r(x),hit:hit(x)})),closeHit:hit(head.querySelector('button')),fieldHit:hit(field),layerCount:e.querySelectorAll('.guest-info-picker-layer').length,headBorder:getComputedStyle(head).borderBottomWidth,headColor:getComputedStyle(head).borderBottomColor,headShadow:getComputedStyle(head).boxShadow,footerBorder:getComputedStyle(footer).borderTopWidth,footerColor:getComputedStyle(footer).borderTopColor,scrollHeight:body.scrollHeight,clientHeight:body.clientHeight,scrollTop:body.scrollTop,bodyBackground:getComputedStyle(body).backgroundColor};});}
 try{
 await section('chooser',async()=>{await fresh();await page.waitForFunction(()=>[...document.querySelectorAll('.role-selection img')].every(e=>e.complete&&e.naturalWidth));const m=await page.locator('.role-selection').evaluate(e=>{const r=x=>x.getBoundingClientRect().toJSON();return{tile:r(e.querySelector('.role-app-logo')),hotel:r(e.querySelector('.role-logo')),rows:[...e.querySelectorAll('.role-options button')].map(b=>({box:r(b),icon:r(b.querySelector('.role-icon')),text:r(b.querySelector('span:not(.role-icon)')),title:r(b.querySelector('strong')),sub:r(b.querySelector('small'))}))};});const svg=await page.evaluate(async()=>{const d=new DOMParser().parseFromString(await(await fetch('/breakfast-app-logo.svg')).text(),'image/svg+xml');return{cup:d.querySelectorAll('path[fill="#ffffff"]').length,steam:d.querySelectorAll('#steam path').length,tile:d.querySelector('rect').outerHTML,effects:d.querySelectorAll('filter,linearGradient,radialGradient,image,text').length};});check('1.filled-logo',svg.cup===2&&svg.steam===2&&svg.effects===0&&m.tile.width===(device==='iphone'?52:60),{svg,...m});const [a,b]=m.rows;check('2.shared-row-alignment',Math.abs((a.title.x-a.box.x)-(b.title.x-b.box.x))<1&&a.title.x===a.sub.x&&b.title.x===b.sub.x&&m.rows.every(v=>Math.abs((v.icon.y+v.icon.height/2)-(v.text.y+v.text.height/2))<1&&Math.abs((v.text.y+v.text.height/2)-(v.box.y+v.box.height/2))<1&&v.text.x-v.icon.right>=20),m);await shot('01-bereichswahl',m);});
 for(const role of ['service','reception'])await section(role+'-menu',async()=>{await fresh(role);const m=await menu();check((role==='service'?'3':'4')+'.single-menu-separators',m.sections.every((s,i)=>(i===0||s.section.top==='1px')&&s.rows.every((r,j)=>r.bottom===(j===s.rows.length-1?'0px':'1px')))&&m.footer.top==='1px',m);if(role==='reception')check('4.menu-text-width',m.items.every(i=>i.text.width>200),m.items);await shot(role==='service'?'02-service-menu':'03-reception-menu',m);});
 await section('weekly',async()=>{await fresh('service');await page.getByRole('button',{name:'Menü öffnen'}).click();await page.locator('[data-menu-action="Statistik"]').click();await page.getByRole('button',{name:/Wochenstatistik/}).click();const m=await page.locator('.empty-stats svg').evaluate(e=>({box:e.getBoundingClientRect().toJSON(),color:getComputedStyle(e).color,fill:getComputedStyle(e).fill,stroke:getComputedStyle(e).strokeWidth,cls:e.getAttribute('class')}));check('5.calendar-outline',m.box.width===22&&m.box.height===22&&m.color==='rgb(28, 119, 123)'&&m.fill==='none'&&m.cls.includes('lucide-calendar-days'),m);await shot('04-weekly-empty',m);});
 await section('reception',async()=>{await fresh('reception');const m=await page.locator('.reception-toolbar').evaluate(e=>({toolbar:e.getBoundingClientRect().toJSON(),summary:e.querySelector('.reception-summary')?.getBoundingClientRect().toJSON(),buttons:[...e.querySelectorAll('.reception-actions button')].map(b=>({box:b.getBoundingClientRect().toJSON(),color:getComputedStyle(b).backgroundColor})),search:document.querySelector('.search-wrap').getBoundingClientRect().toJSON()}));check('6.compact-actions',m.buttons.length===2&&m.buttons[0].box.height===m.buttons[1].box.height&&m.buttons[0].box.y===m.buttons[1].box.y&&m.buttons[1].box.x>m.buttons[0].box.right&&m.buttons.every(b=>b.box.bottom<=m.search.top)&&(device==='iphone'?m.buttons[0].box.height===44:m.buttons[0].box.height===(device==='desktop'?38:46)),m);await shot('05-reception-actions',m);
 const rows=await page.locator('.room-row:visible').evaluateAll(es=>es.filter(e=>['20','21','31'].includes(e.querySelector('.room-number')?.textContent.trim())).map(e=>{const r=x=>x.getBoundingClientRect().toJSON(),note=e.querySelector('.reception-remark'),name=e.querySelector('.guest-names'),people=e.querySelector('.people');return{room:e.querySelector('.room-number').textContent,box:r(e),note:r(note),name:r(name),people:r(people),noteVisible:getComputedStyle(note).display!=='none',hasNote:note.classList.contains('has-remark'),prefix:getComputedStyle(note,'::before').content,text:note.textContent,overflow:getComputedStyle(note).textOverflow};}));const no=rows.find(r=>r.room==='20'),yes=rows.find(r=>r.room==='21');check('7.note-presentation',device==='iphone'?!no.noteVisible&&yes.noteVisible&&yes.note.x===yes.name.x&&yes.note.right<=yes.people.left-10&&yes.prefix.includes('Bemerkung ·')&&yes.overflow==='ellipsis':no.noteVisible&&yes.noteVisible,rows);check('7.reserved-person-column',rows.every(r=>r.name.right<=r.people.left-8),rows);await shot('06-reception-no-note',no);await page.getByRole('button',{name:'Zimmer 21 öffnen'}).scrollIntoViewIfNeeded();await shot('07-reception-synthetic-note',yes);
 await page.getByRole('button',{name:'Zimmer 21 öffnen'}).click();await page.locator('.reception-view-mode').waitFor();check('reception.pointer-and-date',await page.locator('.reception-view-mode').getByText('26.09.2026',{exact:true}).isVisible());await shot('07-reception-detail-frozen');});
 await section('service-detail-editor',async()=>{await fresh('service');await page.getByRole('button',{name:'Zimmer 20 öffnen'}).click();await page.locator('.guest-modal').waitFor();const m=await page.locator('.guest-modal').evaluate(e=>{const footer=e.querySelector('.modal-actions'),b=footer.querySelector('button'),style=getComputedStyle(footer);return{modal:e.getBoundingClientRect().toJSON(),footer:footer.getBoundingClientRect().toJSON(),button:b.getBoundingClientRect().toJSON(),footerContentWidth:footer.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),readOnly:e.querySelectorAll('input,textarea,select').length===0,fields:[...e.querySelectorAll('.detail-item')].map(d=>({radius:getComputedStyle(d).borderRadius,background:getComputedStyle(d).backgroundColor,text:d.textContent}))};});check('8.read-only-detail',m.readOnly&&m.fields.length===3&&m.fields.every(f=>f.radius==='0px'&&f.background==='rgba(0, 0, 0, 0)'),m);check('8.fullwidth-close',Math.abs(m.button.width-m.footerContentWidth)<1,m);await shot('08-service-checked-in-detail',m);
 // Reproduce the actual stale state: request Guest info in read-only detail,
 // close that detail, then open the same guest through the existing edit workflow.
 await page.locator('.guest-info-edit-link').click();await page.locator('.guest-modal > .modal-actions button').click();await page.getByRole('button',{name:'Gäste bearbeiten',exact:true}).click();await page.getByRole('button',{name:'Zimmer 20 öffnen'}).click();await page.locator('.guest-edit-modal').waitFor();if(!before)await page.waitForFunction(()=>!document.querySelector('.guest-edit-modal .guest-info-picker-layer'));const top=await editorMetrics();check('9.no-overlay',top.layerCount===0&&top.fieldHit&&top.closeHit&&top.buttons.every(b=>b.hit),top);check('9.header-footer-separators',top.headBorder==='1px'&&top.headColor==='rgb(220, 227, 225)'&&top.headShadow==='none'&&top.footerBorder==='1px'&&top.footerColor==='rgb(220, 227, 225)',top);check('9.first-label-visible',top.label.top>=top.head.bottom+12,top);await shot('09-editor-no-overlay',top);
 if(!before){await page.locator('.guest-edit-modal textarea').first().click();check('9.field-interactive',await page.locator('.guest-edit-modal textarea').first().evaluate(e=>e===document.activeElement));}
 await page.locator('.guest-edit-modal > .modal-body').evaluate(e=>e.scrollTop=e.scrollHeight);const bottom=await editorMetrics();check('9.scroll-footer',bottom.last.bottom<=bottom.footer.top&&bottom.body.bottom<=bottom.footer.top+1&&Math.abs(bottom.footer.top-top.footer.top)<1&&Math.abs(bottom.buttons[0].box.width-bottom.buttons[1].box.width)<1&&bottom.buttons.every(b=>b.hit),bottom);await shot('10-editor-bottom',bottom);
 if(!before){await page.locator('.guest-edit-modal > .modal-actions .modal-action:not(.primary)').click();await page.locator('.guest-modal:not(.guest-edit-modal)').waitFor();check('9.cancel-returns-detail',await page.locator('.guest-modal .modal-kicker').textContent()==='Zimmer 20');await shot('11-returned-service-detail');await page.locator('.guest-modal > .modal-actions button').click();await page.getByRole('button',{name:'Gäste bearbeiten',exact:true}).click();await page.getByRole('button',{name:'Zimmer 20 öffnen'}).click();await page.locator('.guest-edit-modal .close-button').click();await page.locator('.guest-modal:not(.guest-edit-modal)').waitFor();check('9.close-returns-detail',true);}
 });
 }finally{await context?.close();}
}
(async()=>{for(const engine of (process.env.PHYSICAL_ENGINES||'webkit,chromium').split(',')){let browser;try{const local=engine==='chromium'&&process.env.LOCAL_CHROMIUM;browser=await({chromium,webkit}[engine]).launch(local?{executablePath:process.env.LOCAL_CHROMIUM,args:require(process.env.LOCAL_CHROMIUM_PACKAGE).default.args.filter(a=>a!=='--single-process')}:{headless:true});if(engine==='webkit'&&process.env.BASELINE_PREVIEW_URL)await run(browser,engine,'iphone',390,844,true);for(const [d,w,h]of[['iphone',390,844],['ipad',1024,1366],['desktop',1440,900]])await run(browser,engine,d,w,h);}catch(e){matrix[engine+'.runner']='FAIL';evidence[engine+'.runner']=String(e);}finally{await browser?.close();}}
if(process.env.BASELINE_PREVIEW_URL){
 const prior=beforeObservations['before.webkit.iphone.2.shared-row-alignment']?.data,next=evidence['webkit.iphone.2.shared-row-alignment'];
 const same=(a,b)=>a&&b&&['x','y','width','height'].every(k=>Math.abs(a[k]-b[k])<1);
 const ok=prior&&next&&same(prior.tile,next.tile)&&same(prior.hotel,next.hotel)&&prior.rows.every((r,i)=>same(r.box,next.rows[i].box));
 matrix['frozen.iphone-chooser-outer-geometry']=ok?'PASS':'FAIL';evidence['frozen.iphone-chooser-outer-geometry']={before:prior,after:next};
}
matrix['runtime-errors']=errors.length?'FAIL':'PASS';fs.writeFileSync(path.join(output,'results.json'),JSON.stringify({commit:process.env.SOURCE_SHA,url,baselineUrl:process.env.BASELINE_PREVIEW_URL,matrix,evidence,beforeObservations,screenshots,errors,isolationErrors,conditions:{physicalIphoneApproval:false,supabaseWrites:false,productionWrites:false}},null,2));console.log(JSON.stringify({pass:Object.values(matrix).filter(v=>v==='PASS').length,fail:Object.values(matrix).filter(v=>v==='FAIL').length,screenshots:screenshots.length}));if(Object.values(matrix).includes('FAIL'))process.exitCode=1;})();
